1	import { notFound, redirect } from "next/navigation";
2	import { createClient } from "@/lib/supabase/server";
3	import { signItemImages, displayPath } from "@/lib/storage/signed";
4	import { localDateFor } from "@/lib/outfits/local-date";
5	import { itemWearStats } from "@/lib/closet/wear-stats";
6	import { goesWith } from "@/lib/closet/goes-with";
7	import { ItemDetail, type DetailItem } from "@/components/closet/item-detail";
8	import type { GoesWithCard } from "@/components/closet/item-view";
9	
10	export default async function ItemPage({
11	  params,
12	}: {
13	  params: Promise<{ itemId: string }>;
14	}) {
15	  const { itemId } = await params;
16	  const supabase = await createClient();
17	  const {
18	    data: { user },
19	  } = await supabase.auth.getUser();
20	  if (!user) redirect("/");
21	
22	  const { data: item } = await supabase.from("items").select("*").eq("id", itemId).single();
23	  if (!item) notFound();
24	
25	  // The rest of the wardrobe — used for "Goes with" and the brand suggestions.
26	  const { data: closetRows } = await supabase.from("items").select("*").eq("archived", false);
27	  const closet = closetRows ?? [];
28	
29	  /**
30	   * Wear history for ONE item, in two steps on purpose.
31	   *
32	   * A wear is logged against an OUTFIT, never an item, so an item's wear count
33	   * is "how many logged outfits contained it". `wear_logs` and `outfit_items`
34	   * are NOT directly related — both hang off `outfits` — so PostgREST cannot
35	   * embed one in the other, and an `outfit_items!inner(...)` join silently
36	   * returned zero rows for an item that had genuinely been worn. Two explicit
37	   * queries are obviously correct where that embed was quietly wrong.
38	   */
39	  const { data: wornIn } = await supabase
40	    .from("outfit_items")
41	    .select("outfit_id")
42	    .eq("item_id", itemId);
43	  const outfitIds = (wornIn ?? []).map((r) => r.outfit_id);
44	  const { data: logs } = outfitIds.length
45	    ? await supabase.from("wear_logs").select("worn_on").in("outfit_id", outfitIds)
46	    : { data: [] };
47	
48	  const { data: profile } = await supabase
49	    .from("profiles")
50	    .select("location_timezone")
51	    .eq("id", user.id)
52	    .single();
53	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
54	
55	  const stats = itemWearStats(logs ?? [], item.price, today);
56	
57	  const pairIds = goesWith(
58	    { id: item.id, category: item.category, colors: item.colors ?? [], formality: item.formality },
59	    closet.map((i) => ({
60	      id: i.id,
61	      category: i.category,
62	      colors: i.colors ?? [],
63	      formality: i.formality,
64	    })),
65	  );
66	  const byId = new Map(closet.map((i) => [i.id, i]));
67	  const pairs = pairIds.flatMap((id) => {
68	    const row = byId.get(id);
69	    return row ? [row] : [];
70	  });
71	
72	  const signed = await signItemImages([item, ...pairs].map(displayPath));
73	
74	  const goesWithCards: GoesWithCard[] = pairs.map((i) => ({
75	    id: i.id,
76	    name: i.name ?? i.subcategory ?? i.category,
77	    imageUrl: signed.get(displayPath(i)) ?? "",
78	  }));
