4	import { archiveItem } from "@/app/closet/[itemId]/actions";
5	import type { Tags } from "@/lib/ai/tagging-schema";
6	
7	import { ItemView, type GoesWithCard } from "./item-view";
8	import { ItemEditSheet } from "./item-edit-sheet";
9	import { StyleCta } from "./style-cta";
10	
11	export type DetailItem = {
12	  id: string;
13	  name: string | null;
14	  brand: string | null;
15	  category: Tags["category"];
16	  subcategory: string | null;
17	  colors: string[];
18	  material: string | null;
19	  texture: string | null;
20	  pattern: string | null;
21	  price: number | null;
22	  formality: number | null;
23	  seasons: string[];
24	};
25	
26	/**
27	 * The item detail shell.
28	 *
29	 * This file used to BE the tag form. The design's item detail is read-first —
30	 * cutouts are the hero, the stat tiles answer "how do I actually wear this?",
31	 * and editing sits behind `⋯`. So this component now owns only the switch
32	 * between the two: `ItemView` reads, `ItemEditSheet` writes.
33	 */
34	export function ItemDetail({
35	  item,
36	  imageUrl,
37	  brandSuggestions,
38	  stats,
39	  goesWith,
40	}: {
41	  item: DetailItem;
42	  imageUrl: string;
43	  brandSuggestions: string[];
44	  stats: { wears: number; costPerWear: string | null; lastWorn: string };
45	  goesWith: GoesWithCard[];
46	}) {
47	  const [editing, setEditing] = useState(false);
48	  const [, start] = useTransition();
49	
50	  function archive() {
51	    if (!confirm("Remove this piece from your closet?")) return;
52	    start(async () => {
53	      await archiveItem(item.id);
54	    });
55	  }
56	
57	  return (
58	    <>
59	      <ItemView
60	        item={item}
61	        imageUrl={imageUrl}
62	        stats={stats}
63	        goesWith={goesWith}
64	        onEdit={() => setEditing(true)}
65	        onArchive={archive}
66	        // Built HERE, not passed down from the page. `page.tsx` is a Server
67	        // Component, and a JSX element handed across the RSC boundary is
68	        // serialised — React cannot give it positional identity and warns that
69	        // every child in a list needs a key. Creating it inside this client
70	        // component keeps ItemView presentational without that round trip.
71	        styleCta={<StyleCta itemId={item.id} />}
72	      />
73	      {editing && (
74	        <ItemEditSheet
75	          item={item}
76	          brandSuggestions={brandSuggestions}
77	          onClose={() => setEditing(false)}
78	        />
79	      )}
80	    </>
81	  );
82	}
